  "data_age": {
    "term_id": "data_age",
    "display_name": "Data Age",
    "category": "data_quality",
    "short_definition": "Time since the source published the newest value shown.",
    "full_definition": "For a macro series, time since its newest vintage was released; for SEC data, time since the newest filing was accepted. Different from our last refresh, which is when we fetched it.",
    "formula": "now - publication time of the newest value",
    "unit": "duration",
    "example": "CPI for August 2026, released 2026-09-11: about 25 days old on 2026-10-06.",
    "direction": "Longer = older information",
    "interpretation": "Monthly series are normally weeks old; daily ones a day or two.",
    "why_it_matters": "Separates a stale source from a source that simply publishes rarely.",
    "source": "Publication times from SEC and ALFRED (ADR-013, ADR-015)",
    "source_url": "https://github.com/stevenyang0714/autotrading/blob/main/docs/decisions/DECISIONS.md",
    "as_of": "2026-10-06",
    "update_cadence": "continuous",
    "caveats": "Date-only releases count from the end of that day in New York.",
    "related_terms": [
      "next_refresh",
      "data_freshness",
      "vintage"
    ],
    "methodology_version": "0.1.0",
    "name_zh": "資料年齡",
    "hint_zh": "來源發布最新數值至今經過多久。"
  },
  "data_freshness": {
    "term_id": "data_freshness",
    "display_name": "Data Freshness",
    "category": "data_quality",
    "short_definition": "Time since the latest successful update compared with its expected cadence.",
    "full_definition": "For each enabled source, the time since its last successful ingestion run is compared with the source's freshness SLA. fresh: within the SLA. stale: older than the SLA, or never succeeded. failing: the most recent finished run failed or was dead-lettered. Sources that are not enabled are not judged and show Not enabled.",
    "formula": "now - last_successful_ingest; compared to source freshness SLA -> fresh | stale | failing (not judged when the source is disabled)",
    "unit": "state",
    "example": "SEC EDGAR has a 2-day SLA, so a last success 3 days ago shows stale.",
    "direction": "Longer age = staler",
    "interpretation": "stale means the value is older than it should be for its source; failing means the latest attempt did not work.",
    "why_it_matters": "Stale inputs can block signals and execution eligibility.",
    "source": "Milestone M0.3 freshness monitor; apps/api/src/autotrading/domain/freshness.py",
    "source_url": "https://github.com/stevenyang0714/autotrading/blob/main/apps/api/src/autotrading/domain/freshness.py",
    "as_of": "2026-10-05",
    "update_cadence": "continuous (computed on each request)",
    "caveats": "Some sources update only per filing or weekly, so their SLA is long.",
    "related_terms": [
      "freshness_sla",
      "ingestion_status",
      "as_of"
    ],
    "methodology_version": "0.1.0",
    "name_zh": "資料新鮮度",
    "hint_zh": "距離上次成功更新多久，和該來源的預期更新頻率比較。"
  },
